+                // otherwise nullify
+                : null;
+            var wrapper = BlockUtils.wrapperFor(blockFactory, PlannerUtils.toElementType(dataType), 1);
+            wrapper.accept(value);
+            blocks.add(wrapper.builder().build());
+        }
+    }
